
/**
 * A single authoritative source backing a factual claim on a major.
 * `url` must point at the exact page/document (never a homepage).
 */
export interface MajorSource {
  title: string;
  titleAR?: string;
  url: string;
  /** What claim this source verifies (EN). */
  verifies: string;
  verifiesAR?: string;
  /** ISO date the source was last checked, e.g. "2026-09-06". */
  checked: string;
}

/**
 * Admission requirements split by authority tier so a student can tell a
 * legal/nationwide rule apart from a university-specific one and from Darb's
 * own practical advice. AR/EN arrays must have the same length.
 */
export interface RequirementTiers {
  official: string[];
  officialEN: string[];
  universitySpecific: string[];
  universitySpecificEN: string[];
  darbGuidance: string[];
  darbGuidanceEN: string[];
}


/** Compact "at a glance" facts shown at the top of the major card. AR/EN pairs. */
export interface MajorGlance {
  degree: string; degreeEN: string;
  admissionMode: string; admissionModeEN: string;
  applicationChannel: string; applicationChannelEN: string;
}

/**
 * Structured language requirements (replaces the free-text paragraph when
 * present). Only verified facts; `exceptions` are university-specific.
 */
export interface LanguageProfile {
  teachingLanguage: string; teachingLanguageEN: string;
  requiredLevel: string; requiredLevelEN: string;
  acceptedCertificates: string[]; acceptedCertificatesEN: string[];
  exceptions?: string[]; exceptionsEN?: string[];
  englishOption: string; englishOptionEN: string;
}

export interface SubMajor {
  id: string;
  nameAR: string;
  nameEN: string;
  nameDE?: string;
  description: string;
  descriptionEN: string;
  detailedDescription?: string;
  detailedDescriptionEN?: string;
  duration?: string;
  durationEN?: string;
  careerProspects?: string;
  careerProspectsEN?: string;
  requirements?: string;
  requirementsEN?: string;
  suitableFor?: string;
  suitableForEN?: string;
  requiredBackground?: string;
  requiredBackgroundEN?: string;
  languageRequirements?: string;
  languageRequirementsEN?: string;
  careerOpportunities?: string;
  careerOpportunitiesEN?: string;
  arab48Notes?: string;
  arab48NotesEN?: string;
  /** Tiered admission requirements (official / university-specific / Darb). */
  requirementTiers?: RequirementTiers;
  /** Direct authoritative sources for the claims above. */
  sources?: MajorSource[];
  /** "YYYY-MM" of the last fact-check pass. Shown as "Last verified". */
  lastVerified?: string;
  /** Top-of-card fact chips. */
  glance?: MajorGlance;
  /** Structured language block (preferred over `languageRequirements`). */
  languageProfile?: LanguageProfile;
}

export interface MajorCategory {
  id: string;
  title: string;
  titleEN: string;
  subMajors: SubMajor[];
}

